<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">    runner.run_script(</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;">&quot;shell&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;">&quot;delete-all&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">)</span></span>
